105: // maybeAppend returns (0, false) if the entries cannot be appended. Otherwise,
106: // it returns (last index of new entries, true).
107: func (l *raftLog) maybeAppend(a logSlice, committed uint64) (lastnewi uint64, ok bool) {
108: 	if !l.matchTerm(a.prev) {
109: 		return 0, false
110: 	}
111: 	// TODO(pav-kv): propagate logSlice down the stack. It will be used all the
112: 	// way down in unstable, for safety checks, and for useful bookkeeping.
113: 
114: 	lastnewi = a.prev.index + uint64(len(a.entries))
115: 	check := a.entries
116: 	if len(check) > 1 &&
117: 		check[0].Index == l.lastIndex() &&
118: 		len(check[0].Data) == 0 &&
119: 		len(check[1].Data) > 0 {
120: 		check = check[1:]
121: 	}
122: 	ci := l.findConflict(check)
123: 	switch {
124: 	case ci == 0:
125: 	case ci <= l.committed:
126: 		l.logger.Panicf("entry %d conflict with committed entry [committed(%d)]", ci, l.committed)
127: 	default:
128: 		offset := a.prev.index + 1
129: 		if ci-offset > uint64(len(a.entries)) {
130: 			l.logger.Panicf("index, %d, is out of range [%d]", ci-offset, len(a.entries))
131: 		}
132: 		l.append(a.entries[ci-offset:]...)
133: 	}
134: 	l.commitTo(min(committed, lastnewi))
135: 	return lastnewi, true
