503: // slice returns a slice of log entries from lo through hi-1, inclusive.
504: func (l *raftLog) slice(lo, hi uint64, maxSize entryEncodingSize) ([]pb.Entry, error) {
505: 	if err := l.mustCheckOutOfBounds(lo, hi); err != nil {
506: 		return nil, err
507: 	}
508: 	if lo == hi {
509: 		return nil, nil
510: 	}
511: 	if lo >= l.unstable.offset {
512: 		ents := limitSize(l.unstable.slice(lo, hi), maxSize)
513: 		// NB: use the full slice expression to protect the unstable slice from
514: 		// appends to the returned ents slice.
515: 		return ents[:len(ents):len(ents)], nil
516: 	}
517: 
518: 	cut := min(hi, l.unstable.offset)
519: 	ents, err := l.storage.Entries(lo, cut, uint64(maxSize))
520: 	if err == ErrCompacted {
521: 		return nil, err
522: 	} else if err == ErrUnavailable {
523: 		l.logger.Panicf("entries[%d:%d) is unavailable from storage", lo, cut)
524: 	} else if err != nil {
525: 		panic(err) // TODO(pavelkalinnikov): handle errors uniformly
526: 	}
527: 	if hi <= l.unstable.offset {
528: 		return ents, nil
529: 	}
530: 
531: 	// Fast path to check if ents has reached the size limitation. Either the
532: 	// returned slice is shorter than requested (which means the next entry would
533: 	// bring it over the limit), or a single entry reaches the limit.
534: 	if uint64(len(ents)) < cut-lo {
535: 		return ents, nil
536: 	}
537: 	// Slow path computes the actual total size, so that unstable entries are cut
538: 	// optimally before being copied to ents slice.
539: 	size := entsSize(ents)
540: 	if size >= maxSize {
541: 		return ents, nil
542: 	}
543: 
544: 	unstable := limitSize(l.unstable.slice(l.unstable.offset, hi), maxSize-size)
545: 	// Total size of unstable may exceed maxSize-size only if len(unstable) == 1.
546: 	// If this happens, ignore this extra entry.
547: 	if len(unstable) == 1 && size+entsSize(unstable) > maxSize {
548: 		return ents, nil
549: 	}
550: 	// Otherwise, total size of unstable does not exceed maxSize-size, so total
551: 	// size of ents+unstable does not exceed maxSize. Simply concatenate them.
552: 	return extend(ents, unstable), nil
553: }
